\begin{tikzpicture}[font=\sffamily, line width=0.8pt]
  % beaker with distilled water
  \draw (0,4) -- (0,0) -- (6,0) -- (6,4);
  \dotregion{0}{0}{6}{3}
  \draw (0,3) -- (6,3);
  % Visking tubing bag with concentrated sucrose solution
  \draw[fill=gray!45] (3,1.9) ellipse (0.9cm and 1.0cm);
  % capillary tube with liquid column
  \fill[gray!30] (2.92,2.9) rectangle (3.08,5.2);
  \draw (2.92,2.9) -- (2.92,6.5) -- (3.08,6.5) -- (3.08,2.9);
  % labels with leader lines
  \node[anchor=east] at (1.6,5.2) {liquid level};
  \draw (1.8,5.2) -- (2.92,5.2);
  \node[anchor=west] at (3.8,6.4) {capillary tube};
  \draw (3.75,6.4) -- (3.1,6.3);
  \node[anchor=west] at (4.3,3.4) {Visking tubing};
  \draw (4.25,3.45) -- (3.86,2.2);
  \node[anchor=east] at (5.8,2.0) {distilled water};
  \node at (3,0.5) {concentrated sucrose solution};
  % caption
  \node at (3,-1.0) {Fig. 2.1};
\end{tikzpicture}

